"use client"

import * as React from "react"
import { flushSync } from "react-dom"

import { useDataCellActivationClickTail } from "@/registry/new-york-v4/ui/data-cell-activation"
import { DataCellBooleanControl } from "@/registry/new-york-v4/ui/data-cell-boolean-control"
import type { DataCellControlAction } from "@/registry/new-york-v4/ui/data-cell-control-contract"
import {
  canActivateDataCellFromKey,
  DataCellControl,
  getDataCellClickControlAction,
  getDataCellKeyControlAction,
  getDataCellPointerControlAction,
} from "@/registry/new-york-v4/ui/data-cell-control-registry"
import { DataCellDisplay } from "@/registry/new-york-v4/ui/data-cell-display"
import {
  formatDataCellDisplayValue,
  parseDataCellNumberInput,
} from "@/registry/new-york-v4/ui/data-cell-format"
import { DataCellNumberControl } from "@/registry/new-york-v4/ui/data-cell-number-control"
import { DataCellPickerControl } from "@/registry/new-york-v4/ui/data-cell-picker-control"
import { DataCellSelectControl } from "@/registry/new-york-v4/ui/data-cell-select-control"
import { DataCellTextControl } from "@/registry/new-york-v4/ui/data-cell-text-control"
import type {
  DataCellActivationSource,
  DataCellCommitHandler,
  DataCellProps,
} from "@/registry/new-york-v4/ui/data-cell-types"

export type {
  DataCellActivationSource,
  DataCellCommitValue,
  DataCellDateTimeZone,
  DataCellEditorHandle,
  DataCellKind,
  DataCellMode,
  DataCellProps,
  DataCellSelectOption,
  DataCellValue,
  DataCellValueMeta,
} from "@/registry/new-york-v4/ui/data-cell-types"
export { formatDataCellDisplayValue, parseDataCellNumberInput }
export {
  createDataCellKeyboardActivationSource,
  createDataCellPointerActivationSource,
  createDataCellShellActivationSource,
  type DataCellActivationToken,
} from "@/registry/new-york-v4/ui/data-cell-activation"
export { DataCellBooleanControl }
export { DataCellControl, canActivateDataCellFromKey }
export { DataCellDisplay }
export { DataCellNumberControl }
export { DataCellPickerControl }
export { DataCellSelectControl }
export { DataCellTextControl }

function storeDataCellActivationSource(
  sourceRef: React.MutableRefObject<DataCellActivationSource | undefined>,
  setSource: React.Dispatch<
    React.SetStateAction<DataCellActivationSource | undefined>
  >,
  source: DataCellActivationSource
) {
  flushSync(() => {
    sourceRef.current = source
    setSource(source)
  })
}

function hasDataCellKeyboardModifier(event: React.KeyboardEvent<HTMLElement>) {
  const isAltGraph =
    event.getModifierState("AltGraph") ||
    event.nativeEvent.getModifierState?.("AltGraph") ||
    (event.ctrlKey &&
      event.altKey &&
      event.key.length === 1 &&
      !/^[\x00-\x7F]$/.test(event.key))
  return (
    event.metaKey ||
    (event.ctrlKey && !isAltGraph) ||
    (event.altKey && !isAltGraph) ||
    event.nativeEvent.isComposing
  )
}

export function DataCell({
  mode,
  active,
  editable = false,
  disabled = false,
  onActiveChange,
  onCommit,
  onEditingEnd,
  onEditorHandleChange,
  onClick,
  onKeyDown,
  onPointerDown,
  ...props
}: DataCellProps) {
  const displayRef = React.useRef<HTMLElement>(null)
  const activationClickTail = useDataCellActivationClickTail()
  const activationSourceRef = React.useRef<
    DataCellActivationSource | undefined
  >(undefined)
  const [uncontrolledActive, setUncontrolledActive] = React.useState(false)
  const [activationSource, setActivationSource] =
    React.useState<DataCellActivationSource>()
  const isControlledActive = active !== undefined
  const isExplicitMode = mode !== undefined
  const isActive =
    active ?? (isExplicitMode ? mode === "edit" : uncontrolledActive)
  const canSelfActivate =
    editable && !disabled && (!isExplicitMode || isControlledActive)

  const setActive = React.useCallback(
    (nextActive: boolean) => {
      if (!isControlledActive) setUncontrolledActive(nextActive)
      onActiveChange?.(nextActive)
    },
    [isControlledActive, onActiveChange]
  )

  const endEditing = React.useCallback(() => {
    activationSourceRef.current = undefined
    setActive(false)
    onEditingEnd?.()
  }, [onEditingEnd, setActive])

  const applyControlAction = React.useCallback(
    (
      action: DataCellControlAction,
      event:
        | React.PointerEvent<HTMLElement>
        | React.MouseEvent<HTMLElement>
        | React.KeyboardEvent<HTMLElement>,
      markClickTail: boolean
    ) => {
      if (action.kind === "none") return
      if (action.shouldPreventDefault) event.preventDefault()
      event.stopPropagation()
      if (action.kind === "command") {
        action.commit(onCommit as DataCellCommitHandler | undefined)
        if (markClickTail) activationClickTail.arm()
        return
      }
      storeDataCellActivationSource(
        activationSourceRef,
        setActivationSource,
        action.activationSource
      )
      if (markClickTail) activationClickTail.arm()
      setActive(true)
    },
    [activationClickTail, onCommit, setActive]
  )

  const activateFromPointer = React.useCallback(
    (event: React.PointerEvent<HTMLElement>) => {
      onPointerDown?.(event)
      if (event.defaultPrevented || !canSelfActivate || event.button !== 0) {
        return
      }

      applyControlAction(
        getDataCellPointerControlAction({
          props,
          clientX: event.clientX,
          clientY: event.clientY,
          detail: event.detail,
          displayElement: displayRef.current,
          event: event.nativeEvent,
        }),
        event,
        true
      )
    },
    [applyControlAction, canSelfActivate, onPointerDown, props]
  )

  const activateFromClick = React.useCallback(
    (event: React.MouseEvent<HTMLElement>) => {
      onClick?.(event)
      if (activationClickTail.consume()) {
        event.stopPropagation()
        return
      }
      if (event.defaultPrevented || !canSelfActivate) return

      applyControlAction(
        getDataCellClickControlAction({
          props,
          clientX: event.clientX,
          clientY: event.clientY,
          detail: event.detail,
          displayElement: displayRef.current,
          event: event.nativeEvent,
        }),
        event,
        false
      )
    },
    [activationClickTail, applyControlAction, canSelfActivate, onClick, props]
  )

  const activateFromKey = React.useCallback(
    (event: React.KeyboardEvent<HTMLElement>) => {
      onKeyDown?.(event)
      if (event.defaultPrevented || !canSelfActivate) return

      if (hasDataCellKeyboardModifier(event)) return

      applyControlAction(
        getDataCellKeyControlAction({ props, key: event.key }),
        event,
        false
      )
    },
    [applyControlAction, canSelfActivate, onKeyDown, props]
  )

  if (isActive) {
    return (
      <DataCellControl
        {...props}
        editable={editable}
        disabled={disabled}
        activationSource={
          props.activationSource ??
          activationSource ??
          activationSourceRef.current
        }
        autoFocus={props.autoFocus ?? canSelfActivate}
        onCommit={onCommit as never}
        onEditingEnd={endEditing}
        onEditorHandleChange={onEditorHandleChange}
        onKeyDown={onKeyDown}
      />
    )
  }

  return (
    <DataCellDisplay
      {...props}
      ref={displayRef}
      editable={editable}
      disabled={disabled}
      onPointerDown={activateFromPointer}
      onClick={activateFromClick}
      onKeyDown={activateFromKey}
      tabIndex={editable && !disabled ? (props.tabIndex ?? 0) : props.tabIndex}
    />
  )
}

"use client"

import * as React from "react"

let dataCellActivationTokenId = 0

export type DataCellActivationToken = {
  id: string
  ownsEvent: (event: Event | undefined) => boolean
  release: () => void
}

export type DataCellShellActivationRelease = "microtask" | "click-tail"

export type DataCellActivationSource =
  | {
      kind: "pointer"
      token: DataCellActivationToken
      clientX: number
      clientY: number
      detail: number
      selectionOffset?: number
    }
  | {
      kind: "keyboard"
      key: string
    }
  | {
      kind: "shell"
      token: DataCellActivationToken
      release: DataCellShellActivationRelease
    }

export type DataCellDismissCause =
  | {
      kind: "outside-pointer"
      event: PointerEvent
    }
  | {
      kind: "trigger-press"
      event?: Event
    }
  | {
      kind: "focus-out"
      event?: Event
    }
  | {
      kind: "cancel-open"
      event?: Event
    }
  | {
      kind: "escape"
      event: KeyboardEvent
    }
  | {
      kind: "unknown"
      event?: Event
    }

export type DataCellOpeningContext = {
  source: DataCellActivationSource | undefined
  isOpening: () => boolean
  shouldCancelDismiss: (cause: DataCellDismissCause) => boolean
  release: () => void
}

export function createDataCellPointerActivationSource({
  clientX,
  clientY,
  detail,
  event,
}: {
  clientX: number
  clientY: number
  detail: number
  event?: Event
}): Extract<DataCellActivationSource, { kind: "pointer" }> {
  return {
    kind: "pointer",
    token: createDataCellActivationToken(event, {
      ownUntilReleasedWhenEventMissing: true,
      ownOpeningTailUntilReleasedWhenEventMissing: event === undefined,
    }),
    clientX,
    clientY,
    detail,
  }
}

export function createDataCellKeyboardActivationSource(
  key: string
): Extract<DataCellActivationSource, { kind: "keyboard" }> {
  return {
    kind: "keyboard",
    key,
  }
}

export function createDataCellShellActivationSource(
  event?: Event
): Extract<DataCellActivationSource, { kind: "shell" }> {
  return {
    kind: "shell",
    token: createDataCellActivationToken(event, {
      ownUntilReleasedWhenEventMissing: true,
    }),
    release: event?.type === "click" ? "microtask" : "click-tail",
  }
}

export function createDataCellActivationToken(
  openingEvent?: Event,
  {
    ownUntilReleasedWhenEventMissing = false,
    ownOpeningTailUntilReleasedWhenEventMissing = false,
  }: {
    ownUntilReleasedWhenEventMissing?: boolean
    ownOpeningTailUntilReleasedWhenEventMissing?: boolean
  } = {}
): DataCellActivationToken {
  const id = `data-cell-activation-${++dataCellActivationTokenId}`
  let isReleased = false
  const openingPoint = openingEvent ? getDataCellEventPoint(openingEvent) : null

  return {
    id,
    ownsEvent(event) {
      if (isReleased) return false
      if (!event) return ownUntilReleasedWhenEventMissing
      if (openingEvent && event === openingEvent) return true
      if (!openingEvent && ownOpeningTailUntilReleasedWhenEventMissing) {
        return isDataCellOpeningTailEvent(event)
      }
      if (openingPoint && isDataCellOpeningEventTail(event, openingPoint)) {
        return true
      }
      return false
    },
    release() {
      isReleased = true
    },
  }
}

export function useDataCellOpeningContext(
  activationSource: DataCellActivationSource | undefined,
  {
    enabled,
  }: {
    enabled: boolean
  }
): DataCellOpeningContext {
  const openingSourceRef = React.useRef<DataCellActivationSource | undefined>(
    undefined
  )
  const releaseOpeningRef = React.useRef<(() => void) | null>(null)

  const release = React.useCallback(() => {
    openingSourceRef.current = undefined
    releaseOpeningRef.current?.()
    releaseOpeningRef.current = null
  }, [])

  React.useLayoutEffect(() => {
    release()
    if (!enabled || !activationSource || activationSource.kind === "keyboard") {
      return
    }

    openingSourceRef.current = activationSource
    releaseOpeningRef.current = holdDataCellActivationThroughOpeningEvent(
      activationSource,
      {
        releaseAfterMicrotask:
          activationSource.kind === "pointer" ||
          shouldReleaseDataCellOpeningAfterMicrotask(activationSource),
      }
    )
  }, [activationSource, enabled, release])

  React.useEffect(() => release, [release])

  return React.useMemo(
    () => ({
      source: activationSource,
      isOpening: () => openingSourceRef.current !== undefined,
      shouldCancelDismiss: (cause) =>
        shouldCancelDataCellOpeningDismiss(openingSourceRef.current, cause),
      release,
    }),
    [activationSource, release]
  )
}

export function useDataCellActivationClickTail() {
  const isArmedRef = React.useRef(false)

  return React.useMemo(
    () => ({
      arm() {
        isArmedRef.current = true
      },
      consume() {
        if (!isArmedRef.current) return false
        isArmedRef.current = false
        return true
      },
    }),
    []
  )
}

function holdDataCellActivationThroughOpeningEvent(
  activation: DataCellActivationSource | undefined,
  {
    releaseAfterMicrotask = false,
  }: {
    releaseAfterMicrotask?: boolean
  } = {}
) {
  if (!activation || activation.kind === "keyboard") return () => {}

  const release = () => activation.token.release()
  const releaseAfterDocumentClick = () => queueMicrotask(release)
  const releaseBeforeNewPointer = (event: PointerEvent) => {
    if (!activation.token.ownsEvent(event)) release()
  }
  if (typeof document !== "undefined") {
    document.addEventListener("pointerdown", releaseBeforeNewPointer)
    document.addEventListener("click", releaseAfterDocumentClick, {
      once: true,
    })
  }
  if (releaseAfterMicrotask) queueMicrotask(release)

  return () => {
    activation.token.release()
    if (typeof document !== "undefined") {
      document.removeEventListener("pointerdown", releaseBeforeNewPointer)
      document.removeEventListener("click", releaseAfterDocumentClick)
    }
  }
}

function shouldCancelDataCellOpeningDismiss(
  activationSource: DataCellActivationSource | undefined,
  cause: DataCellDismissCause
) {
  if (!activationSource || activationSource.kind === "keyboard") return false
  if (!isDataCellOpeningDismissCause(activationSource, cause)) return false

  return (
    activationSource.token.ownsEvent(cause.event) ||
    (isDataCellEventlessOpeningDismissCause(cause) &&
      activationSource.token.ownsEvent(undefined))
  )
}

function isDataCellOpeningDismissCause(
  activationSource: Exclude<DataCellActivationSource, { kind: "keyboard" }>,
  cause: DataCellDismissCause
) {
  if (cause.kind === "escape") return false
  if (activationSource.kind === "shell") return true
  return (
    cause.kind === "outside-pointer" ||
    cause.kind === "trigger-press" ||
    cause.kind === "focus-out" ||
    cause.kind === "cancel-open"
  )
}

function isDataCellEventlessOpeningDismissCause(cause: DataCellDismissCause) {
  return (
    cause.kind === "trigger-press" ||
    cause.kind === "focus-out" ||
    cause.kind === "cancel-open" ||
    cause.kind === "unknown"
  )
}

function shouldReleaseDataCellOpeningAfterMicrotask(
  activationSource: DataCellActivationSource
) {
  return (
    activationSource.kind === "shell" &&
    activationSource.release === "microtask"
  )
}

function getDataCellEventPoint(event: Event) {
  if (
    !("clientX" in event) ||
    !("clientY" in event) ||
    typeof event.clientX !== "number" ||
    typeof event.clientY !== "number"
  ) {
    return null
  }
  return {
    clientX: event.clientX,
    clientY: event.clientY,
  }
}

function isDataCellOpeningEventTail(
  event: Event,
  openingPoint: { clientX: number; clientY: number }
) {
  if (!isDataCellOpeningTailEvent(event)) return false
  const eventPoint = getDataCellEventPoint(event)
  return (
    eventPoint !== null &&
    eventPoint.clientX === openingPoint.clientX &&
    eventPoint.clientY === openingPoint.clientY
  )
}

function isDataCellOpeningTailEvent(event: Event) {
  return (
    event.type === "click" ||
    event.type === "pointerup" ||
    event.type === "mouseup"
  )
}

"use client"

import * as React from "react"
import { CheckIcon, XIcon } from "lucide-react"

import { cn } from "@/lib/utils"
import {
  dataCellBooleanDisplayClass,
  dataCellCheckboxDisplayClass,
} from "@/registry/new-york-v4/ui/data-cell-classes"
import type {
  DataCellCommitHandler,
  DataCellProps,
} from "@/registry/new-york-v4/ui/data-cell-types"

export type DataCellBooleanControlProps = DataCellProps & { kind: "boolean" }

export function commitDataCellBooleanToggle(
  value: DataCellBooleanControlProps["value"],
  onCommit: DataCellCommitHandler | undefined
) {
  const nextValue = !Boolean(value)
  onCommit?.(nextValue, {
    kind: "boolean",
    rawValue: String(nextValue),
    isEmpty: false,
    isValid: true,
  })
}

export function DataCellBooleanIndicator({ checked }: { checked: boolean }) {
  return (
    <span
      data-slot="checkbox-indicator"
      className={cn(
        "flex items-center justify-center transition-none",
        checked ? "text-current" : "text-muted-foreground/72"
      )}
    >
      {checked ? (
        <CheckIcon className="size-3.5" />
      ) : (
        <XIcon className="size-3.5" />
      )}
    </span>
  )
}

export function DataCellBooleanControl({
  kind,
  value,
  editable: _editable,
  active: _active,
  mode: _mode,
  disabled = false,
  name,
  className,
  formatValue: _formatValue,
  draftValue: _draftValue,
  placeholder: _placeholder,
  dateTimeZone: _dateTimeZone,
  showPickerIcon: _showPickerIcon,
  activationSource: _activationSource,
  isPickerOpen: _isPickerOpen,
  autoFocus,
  onDraftValueChange: _onDraftValueChange,
  onCommit,
  onEditingEnd,
  onActiveChange: _onActiveChange,
  onPickerOpenChange: _onPickerOpenChange,
  onEditorHandleChange,
  onFocus,
  onBlur,
  onKeyDown,
  onClick,
  onDoubleClick,
  ...props
}: DataCellBooleanControlProps) {
  const checked = Boolean(value)
  const {
    id,
    "aria-label": ariaLabel,
    "aria-describedby": ariaDescribedBy,
    "aria-invalid": ariaInvalid,
    ...rootProps
  } = props

  React.useLayoutEffect(() => {
    onEditorHandleChange?.({
      finish: () => onEditingEnd?.(),
      cancel: () => onEditingEnd?.(),
    })
    return () => onEditorHandleChange?.(null)
  }, [onEditingEnd, onEditorHandleChange])

  return (
    <div
      {...rootProps}
      data-slot="data-cell"
      data-kind={kind}
      data-mode="edit"
      className={cn(
        dataCellBooleanDisplayClass,
        "justify-center px-1",
        className
      )}
    >
      <button
        type="button"
        role="checkbox"
        id={id}
        name={name}
        aria-checked={checked}
        aria-describedby={ariaDescribedBy}
        aria-invalid={ariaInvalid}
        aria-label={ariaLabel ?? (checked ? "true" : "false")}
        data-state={checked ? "checked" : "unchecked"}
        disabled={disabled}
        autoFocus={autoFocus}
        className={cn(
          dataCellCheckboxDisplayClass,
          "flex items-center justify-center"
        )}
        onClick={(event) => {
          event.stopPropagation()
          if (disabled) return
          commitDataCellBooleanToggle(
            value,
            onCommit as DataCellCommitHandler | undefined
          )
          onClick?.(event)
        }}
        onFocus={onFocus}
        onBlur={(event) => {
          onEditingEnd?.()
          onBlur?.(event)
        }}
        onKeyDown={(event) => {
          onKeyDown?.(event)
          if (event.defaultPrevented || event.key !== "Escape") return
          onEditingEnd?.()
          event.currentTarget.blur()
          event.preventDefault()
        }}
        onDoubleClick={onDoubleClick}
      >
        <DataCellBooleanIndicator checked={checked} />
      </button>
    </div>
  )
}

export const dataCellDisplayClass =
  "relative inline-flex w-full rounded-lg bg-transparent text-base text-foreground ring-ring/24 transition-shadow sm:text-sm"

export const dataCellDisplayValueClass =
  "flex h-8.5 w-full min-w-0 items-center rounded-[inherit] px-3 leading-8.5 sm:h-7.5 sm:leading-7.5"

export const dataCellPickerTriggerClass =
  "relative inline-flex h-8.5 w-full min-w-0 shrink-0 cursor-pointer items-center justify-between gap-2 overflow-hidden rounded-lg bg-transparent px-3 text-base font-normal whitespace-nowrap text-foreground transition-colors outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1 focus-visible:ring-offset-background disabled:pointer-events-none disabled:opacity-64 sm:h-7.5 sm:text-sm pointer-coarse:after:absolute pointer-coarse:after:size-full pointer-coarse:after:min-h-11 pointer-coarse:after:min-w-11 [&_svg]:pointer-events-none [&_svg]:-mx-0.5 [&_svg]:shrink-0 [&_svg:not([class*='opacity-'])]:opacity-80 [&_svg:not([class*='size-'])]:size-4.5 sm:[&_svg:not([class*='size-'])]:size-4"

export const dataCellBooleanDisplayClass =
  "flex h-8 w-full min-w-0 items-center overflow-hidden rounded-lg bg-transparent px-3 text-sm text-foreground ring-ring/24 transition-shadow"

export const dataCellCheckboxDisplayClass =
  "peer bg-transparent data-[state=checked]:bg-primary data-[state=checked]:text-primary-foreground dark:data-[state=checked]:bg-primary focus-visible:ring-ring/50 aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 size-4 shrink-0 rounded-[4px] transition-shadow outline-none focus-visible:ring-[3px] disabled:cursor-not-allowed disabled:opacity-50"

import type * as React from "react"

import type {
  DataCellActivationSource,
  DataCellCommitHandler,
  DataCellProps,
} from "@/registry/new-york-v4/ui/data-cell-types"

export type DataCellControlPointerActionArgs = {
  props: DataCellProps
  clientX: number
  clientY: number
  detail: number
  displayElement: HTMLElement | null
  event?: Event
}

export type DataCellControlKeyActionArgs = {
  props: DataCellProps
  key: string
}

export type DataCellControlAction =
  | {
      kind: "none"
    }
  | {
      kind: "edit"
      activationSource: DataCellActivationSource
      shouldPreventDefault: boolean
    }
  | {
      kind: "command"
      commit: (onCommit: DataCellCommitHandler | undefined) => void
      shouldPreventDefault: boolean
    }

export type DataCellControlAdapter = {
  Control: React.ComponentType<DataCellProps>
  activatePointer: (
    args: DataCellControlPointerActionArgs
  ) => DataCellControlAction
  activateClick: (
    args: DataCellControlPointerActionArgs
  ) => DataCellControlAction
  activateKey: (args: DataCellControlKeyActionArgs) => DataCellControlAction
  canActivateFromKey: (key: string) => boolean
}

export function noneDataCellControlAction(): DataCellControlAction {
  return { kind: "none" }
}

export function editDataCellControlAction(
  activationSource: DataCellActivationSource,
  { shouldPreventDefault }: { shouldPreventDefault: boolean }
): DataCellControlAction {
  return {
    kind: "edit",
    activationSource,
    shouldPreventDefault,
  }
}

export function commandDataCellControlAction(
  commit: (onCommit: DataCellCommitHandler | undefined) => void,
  { shouldPreventDefault }: { shouldPreventDefault: boolean }
): DataCellControlAction {
  return {
    kind: "command",
    commit,
    shouldPreventDefault,
  }
}

"use client"

import * as React from "react"

import {
  createDataCellKeyboardActivationSource,
  createDataCellPointerActivationSource,
} from "@/registry/new-york-v4/ui/data-cell-activation"
import {
  commitDataCellBooleanToggle,
  DataCellBooleanControl,
} from "@/registry/new-york-v4/ui/data-cell-boolean-control"
import {
  commandDataCellControlAction,
  editDataCellControlAction,
  noneDataCellControlAction,
  type DataCellControlAction,
  type DataCellControlAdapter,
  type DataCellControlKeyActionArgs,
  type DataCellControlPointerActionArgs,
} from "@/registry/new-york-v4/ui/data-cell-control-contract"
import {
  canActivateDataCellNumberFromKey,
  DataCellNumberControl,
} from "@/registry/new-york-v4/ui/data-cell-number-control"
import { DataCellPickerControl } from "@/registry/new-york-v4/ui/data-cell-picker-control"
import { DataCellSelectControl } from "@/registry/new-york-v4/ui/data-cell-select-control"
import {
  DataCellTextControl,
  getDataCellTextPointerActivationSource,
} from "@/registry/new-york-v4/ui/data-cell-text-control"
import type {
  DataCellKind,
  DataCellProps,
} from "@/registry/new-york-v4/ui/data-cell-types"

const keyboardOpenKeys = new Set(["Enter", "F2", " "])

const textControlAdapter: DataCellControlAdapter = {
  Control: DataCellTextControl as React.ComponentType<DataCellProps>,
  activatePointer: (args) =>
    editDataCellControlAction(
      getDataCellTextPointerActivationSource({
        clientX: args.clientX,
        clientY: args.clientY,
        detail: args.detail,
        displayElement: args.displayElement,
        event: args.event,
        value: args.props.value as string | null | undefined,
      }),
      { shouldPreventDefault: true }
    ),
  activateClick: (args) =>
    editDataCellControlAction(
      getDataCellTextPointerActivationSource({
        clientX: args.clientX,
        clientY: args.clientY,
        detail: args.detail,
        displayElement: args.displayElement,
        event: args.event,
        value: args.props.value as string | null | undefined,
      }),
      { shouldPreventDefault: false }
    ),
  activateKey: ({ key }) =>
    editDataCellControlAction(createDataCellKeyboardActivationSource(key), {
      shouldPreventDefault: true,
    }),
  canActivateFromKey: (key) =>
    key === "Enter" || key === "F2" || key.length === 1,
}

function createInputControlAdapter(
  kind: "number" | "integer"
): DataCellControlAdapter {
  return {
    Control: DataCellNumberControl as React.ComponentType<DataCellProps>,
    activatePointer: createDefaultPointerEditAction,
    activateClick: createDefaultClickEditAction,
    activateKey: ({ key }) =>
      editDataCellControlAction(createDataCellKeyboardActivationSource(key), {
        shouldPreventDefault: true,
      }),
    canActivateFromKey: (key) => canActivateDataCellNumberFromKey(kind, key),
  }
}

const booleanControlAdapter: DataCellControlAdapter = {
  Control: DataCellBooleanControl as React.ComponentType<DataCellProps>,
  activatePointer: ({ props }) =>
    commandDataCellControlAction(
      (onCommit) =>
        commitDataCellBooleanToggle(
          props.value as boolean | null | undefined,
          onCommit
        ),
      { shouldPreventDefault: true }
    ),
  activateClick: ({ props }) =>
    commandDataCellControlAction(
      (onCommit) =>
        commitDataCellBooleanToggle(
          props.value as boolean | null | undefined,
          onCommit
        ),
      { shouldPreventDefault: false }
    ),
  activateKey: ({ key, props }) => {
    if (key !== " ") {
      return editDataCellControlAction(
        createDataCellKeyboardActivationSource(key),
        {
          shouldPreventDefault: true,
        }
      )
    }
    return commandDataCellControlAction(
      (onCommit) =>
        commitDataCellBooleanToggle(
          props.value as boolean | null | undefined,
          onCommit
        ),
      { shouldPreventDefault: true }
    )
  },
  canActivateFromKey: (key) => key === "Enter" || key === "F2" || key === " ",
}

const selectControlAdapter: DataCellControlAdapter = {
  Control: DataCellSelectControl as React.ComponentType<DataCellProps>,
  activatePointer: noneDataCellControlAction,
  activateClick: createDefaultClickEditAction,
  activateKey: createKeyboardOpenAction,
  canActivateFromKey: (key) => keyboardOpenKeys.has(key),
}

const pickerControlAdapter: DataCellControlAdapter = {
  Control: DataCellPickerControl as React.ComponentType<DataCellProps>,
  activatePointer: createDefaultPointerEditAction,
  activateClick: createDefaultClickEditAction,
  activateKey: createKeyboardOpenAction,
  canActivateFromKey: (key) => keyboardOpenKeys.has(key),
}

const numberControlAdapter = createInputControlAdapter("number")
const integerControlAdapter = createInputControlAdapter("integer")

export function getDataCellControlAdapter(
  kind: DataCellKind
): DataCellControlAdapter {
  if (kind === "text") return textControlAdapter
  if (kind === "number") return numberControlAdapter
  if (kind === "integer") return integerControlAdapter
  if (kind === "boolean") return booleanControlAdapter
  if (kind === "select") return selectControlAdapter
  return pickerControlAdapter
}

export function DataCellControl(props: DataCellProps) {
  const Control = getDataCellControlAdapter(props.kind).Control
  return <Control {...props} />
}

export function getDataCellPointerControlAction(
  args: DataCellControlPointerActionArgs
): DataCellControlAction {
  return getDataCellControlAdapter(args.props.kind).activatePointer(args)
}

export function getDataCellClickControlAction(
  args: DataCellControlPointerActionArgs
): DataCellControlAction {
  return getDataCellControlAdapter(args.props.kind).activateClick(args)
}

export function getDataCellKeyControlAction(
  args: DataCellControlKeyActionArgs
): DataCellControlAction {
  if (!canActivateDataCellFromKey(args.props.kind, args.key)) {
    return noneDataCellControlAction()
  }
  return getDataCellControlAdapter(args.props.kind).activateKey(args)
}

export function canActivateDataCellFromKey(
  kind: DataCellKind,
  key: string
): boolean {
  return getDataCellControlAdapter(kind).canActivateFromKey(key)
}

function createDefaultPointerEditAction({
  clientX,
  clientY,
  detail,
  event,
}: DataCellControlPointerActionArgs): DataCellControlAction {
  return editDataCellControlAction(
    createDataCellPointerActivationSource({ clientX, clientY, detail, event }),
    { shouldPreventDefault: true }
  )
}

function createDefaultClickEditAction({
  clientX,
  clientY,
  detail,
  event,
}: DataCellControlPointerActionArgs): DataCellControlAction {
  return editDataCellControlAction(
    createDataCellPointerActivationSource({ clientX, clientY, detail, event }),
    { shouldPreventDefault: false }
  )
}

function createKeyboardOpenAction({
  key,
}: DataCellControlKeyActionArgs): DataCellControlAction {
  return editDataCellControlAction(
    createDataCellKeyboardActivationSource(key),
    {
      shouldPreventDefault: true,
    }
  )
}

